 WHERE sistema_destino = 'PRODUCE' AND tipo_fuente_id IN (12,13,14,17);
UPDATE core.integraciones SET protocolo_sincronizacion = 'batch_sftp'
 WHERE sistema_destino = 'PRODUCE' AND tipo_fuente_id = 15;

