ALTER TABLE mype.ejecucion_nec ENABLE ROW LEVEL SECURITY;
ALTER TABLE mype.ejecucion_nec FORCE ROW LEVEL SECURITY;
CREATE POLICY p_clasif ON mype.ejecucion_nec FOR SELECT
